244	    /**
245	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
246	     * source of truth for how an email is persisted, so inputs that differ only in letter case
247	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
248	     * (create and update, mapper or hand-copied) stores the same canonical value.
249	     *
250	     * @param email the raw email, possibly {@code null}
251	     * @return the lower-cased form, or {@code null} if the input was {@code null}
252	     */
253	    public static String normalizeEmail(String email) {
254	        return email == null ? null : email.toLowerCase();
255	    }
256	
257	    /**
258	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
259	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
260	     */
261	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
262	        "mailinator.com",
263	        "tempmail.com",
264	        "guerrillamail.com");
265	
266	    /**
267	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
268	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
269	     * This is the single source of truth for which email domains are rejected, shared by any
270	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
271	     *
272	     * @param email the owner's email, possibly {@code null}
273	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
274	     */
275	    public static boolean isDisposableEmailDomain(String email) {
276	        if (email == null) {
277	            return false;
278	        }
279	        int at = email.lastIndexOf('@');
280	        if (at < 0) {
281	            return false;
282	        }
283	        String domain = email.substring(at + 1).toLowerCase();
284	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
285	    }
286	
287	    /**
288	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
289	     * truth for how a telephone is compared and persisted, so inputs that differ only in
290	     * formatting (spaces, dashes, brackets) are treated as the same number.
291	     *
292	     * <p>The rules are:
293	     * <ul>
294	     *   <li>spaces, dashes and brackets are stripped;</li>
295	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
296	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
297	     *       is dropped from the national digits;</li>
298	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
299	     *   <li>for a recognized country code the national number (the digits after the country
300	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
301	     *       digits and {@code '+1'} requires 10.</li>
302	     * </ul>
303	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
304	     * values are returned unchanged.
305	     *
306	     * @param telephone the raw telephone, possibly {@code null}
307	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
308	     *     valid E.164 number
309	     */
310	    public static String normalizeTelephone(String telephone) {
311	        if (telephone == null) {
312	            return null;
313	        }
314	        String trimmed = telephone.trim();
315	        boolean hasCountryCode = trimmed.startsWith("+");
316	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
317	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
318	        if (hasCountryCode) {
319	            stripped = stripped.substring(1);
320	        }
321	        if (!stripped.matches("\\d+")) {
322	            return null;
323	        }
324	        String digits;
325	        if (hasCountryCode) {
326	            digits = stripped;
327	        } else {
328	            if (stripped.startsWith("0")) {
329	                stripped = stripped.substring(1);
330	            }
331	            digits = "61" + stripped;
332	        }
333	        if (digits.length() < 8 || digits.length() > 15) {
334	            return null;
335	        }
336	        if (!hasValidNationalNumberLength(digits)) {
337	            return null;
338	        }
339	        return "+" + digits;
340	    }
341	
342	    /**
343	     * Format a stored E.164 telephone for human display: the country code, a space, then the
344	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
345	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
346	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
347	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
348	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
349	     * kept unchanged elsewhere.
350	     *
351	     * @param telephone the stored E.164 telephone, possibly {@code null}
352	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
353	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
354	     *     unchanged
355	     */
356	    public static String telephoneDisplay(String telephone) {
357	        if (telephone == null) {
358	            return null;
359	        }
360	        if (!telephone.matches("\\+\\d+")) {
361	            return telephone;
362	        }
363	        String digits = telephone.substring(1);
364	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
365	            if (digits.startsWith(countryCode)) {
366	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
367	            }
368	        }
369	        return "+" + groupDigits(digits);
370	    }
371	
372	    /**
373	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
374	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
375	     * {@code "412345678"} becomes {@code "412 345 678"}).
376	     *
377	     * @param digits the national digits
378	     * @return the space-grouped digits
379	     */
380	    private static String groupDigits(String digits) {
381	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
382	        for (int i = 0; i < digits.length(); i++) {
383	            if (i > 0 && i % 3 == 0) {
384	                grouped.append(' ');
385	            }
386	            grouped.append(digits.charAt(i));
387	        }
388	        return grouped.toString();
389	    }
390	
391	    /**
392	     * Required national-number length (the count of digits after the country code) for each
393	     * recognized country code, longest country code first so the prefix match is unambiguous.
394	     */
395	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
396	    static {
397	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
398	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
399	    }
400	
401	    /**
402	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
403	     * length its country code requires. A country code with no registered length places no
404	     * additional constraint and is accepted.
405	     *
406	     * @param digits the E.164 digits without the leading {@code '+'}
407	     * @return {@code true} if the national-number length is valid for the country code
408	     */
409	    private static boolean hasValidNationalNumberLength(String digits) {
410	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
411	            String countryCode = entry.getKey();
412	            if (digits.startsWith(countryCode)) {
413	                return digits.length() - countryCode.length() == entry.getValue();
414	            }
415	        }
416	        return true;
417	    }
418	
419	    /**
420	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
421	     * upper-cased abbreviation.
422	     */
423	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
424	        "ST", "STREET",
425	        "RD", "ROAD",
426	        "AVE", "AVENUE");
427	
428	    /**
429	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
430	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
431	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
432	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
433	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
434	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
435	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
436	     * value. The transform is idempotent: a normalized address normalizes to itself.
437	     *
438	     * @param address the raw address, possibly {@code null}
439	     * @return the normalized form, or {@code null} if the input was {@code null}
440	     */
441	    public static String normalizeAddress(String address) {
442	        if (address == null) {
443	            return null;
444	        }
445	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
446	        if (collapsed.isEmpty()) {
447	            return collapsed;
448	        }
449	        String[] tokens = collapsed.split(" ");
450	        StringBuilder normalized = new StringBuilder(collapsed.length());
451	        for (int i = 0; i < tokens.length; i++) {
452	            if (i > 0) {
453	                normalized.append(' ');
454	            }
455	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
456	        }
457	        return normalized.toString();
458	    }
459	
460	    /**
461	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
462	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
463	     * result is that line, with a single space and {@code addressLine2} appended when the second line
464	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
465	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
466	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
467	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
468	     *
469	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
470	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
471	     * @param flatAddress the normalized flat address, possibly {@code null}
472	     * @return the composed address, or the flat value / {@code null} when no structured line is present
473	     */
474	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
475	        if (isPresent(addressLine1)) {
476	            if (isPresent(addressLine2)) {
477	                return addressLine1 + " " + addressLine2;
478	            }
479	            return addressLine1;
480	        }
481	        return flatAddress;
482	    }
483	
484	    /**
485	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
486	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
487	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
488	     *
489	     * @param value the address field, possibly {@code null}
490	     * @return {@code true} if the value is present and non-blank
491	     */
492	    private static boolean isPresent(String value) {
493	        return value != null && !value.isBlank();
494	    }
495	
496	    /**
497	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
498	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
499	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
500	     *
501	     * @param addressLine1 the structured first line, possibly {@code null}
502	     * @param address the flat address, possibly {@code null}
503	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
504	     */
505	    public static boolean hasAddress(String addressLine1, String address) {
506	        return isPresent(addressLine1) || isPresent(address);
507	    }
508	
509	    /**
510	     * Normalize a household field (such as last name or address) to its canonical form for
511	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
512	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
513	     * that differ only in letter case or spacing are treated as the same value.
514	     *
515	     * @param value the raw field value, possibly {@code null}
516	     * @return the normalized form, or {@code null} if the input was {@code null}
517	     */
518	    public static String normalizeHousehold(String value) {
519	        if (value == null) {
520	            return null;
521	        }
522	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
523	    }
524	
525	    /**
526	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
527	     * last name (compared case-insensitively with collapsed whitespace, see
528	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
529	     * those two fields, so two owners who share a last name and postcode are assigned the same id
530	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
531	     * upper-cased hex characters of the SHA-256 digest of
532	     * {@code normalizedLastName + '|' + postcode}.
533	     *
534	     * @param lastName the owner's last name, possibly {@code null}
535	     * @param postcode the owner's postcode, possibly {@code null}
536	     * @return the household id, or {@code null} if either field is {@code null}
537	     */
538	    public static String householdId(String lastName, String postcode) {
539	        String normalizedLastName = normalizeHousehold(lastName);
540	        if (normalizedLastName == null || postcode == null) {
541	            return null;
542	        }
543	        String key = normalizedLastName + "|" + postcode;
544	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
545	    }
546	
547	    /**
548	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
549	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
550	     * so they all agree on algorithm and encoding.
551	     *
552	     * @param value the string to digest, never {@code null}
553	     * @return the 64-character lower-case hex digest
554	     */
555	    private static String sha256Hex(String value) {
556	        try {
557	            byte[] digest = MessageDigest.getInstance("SHA-256")
558	                .digest(value.getBytes(StandardCharsets.UTF_8));
559	            StringBuilder hex = new StringBuilder(digest.length * 2);
560	            for (byte b : digest) {
561	                hex.append(String.format("%02x", b));
562	            }
563	            return hex.toString();
564	        } catch (NoSuchAlgorithmException e) {
565	            // SHA-256 is a standard algorithm required to be present on every JVM.
566	            throw new IllegalStateException("SHA-256 not available", e);
567	        }
568	    }
569	
570	    /**
571	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
572	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
573	     * <ul>
574	     *   <li>{@code REGION} is the region code derived from the postcode (see
575	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
576	     *       in no known range, and</li>
577	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
578	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
579	     *       name.</li>
580	     * </ul>
581	     * The value is deterministic in the postcode, telephone and last name (e.g.
582	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
583	     *
584	     * @param postcode the owner's postcode, possibly {@code null}
585	     * @param telephone the owner's raw telephone, possibly {@code null}
586	     * @param lastName the owner's last name, possibly {@code null}
587	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
588	     */
589	    public static String customerCode(String postcode, String telephone, String lastName) {
590	        if (telephone == null || lastName == null) {
591	            return null;
592	        }
593	        String region = regionForPostcode(postcode);
594	        if (region == null) {
595	            region = "UNKNOWN";
596	        }
597	        String normalizedTelephone = normalizeTelephone(telephone);
598	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
599	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
600	    }
601	
602	    /**
603	     * Compute an owner's {@code identityKey}, the single derived value through which all
604	     * duplicate detection is now expressed. It consolidates the three formerly separate
605	     * telephone, email and household duplicate checks into one key, formatted as
606	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
607	     * <ul>
608	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
609	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
610	     *       when no email is present, and</li>
611	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
612	     * </ul>
613	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
614	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
615	     * members of the same household with different telephones have different keys.
616	     *
617	     * @param telephone the owner's raw telephone, possibly {@code null}
618	     * @param email the owner's email, possibly {@code null}
619	     * @param lastName the owner's last name, possibly {@code null}
620	     * @param postcode the owner's postcode, possibly {@code null}
621	     * @return the identity key, never {@code null}
622	     */
623	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
624	        String normalizedTelephone = normalizeTelephone(telephone);
625	        String normalizedEmail = normalizeEmail(email);
626	        String household = householdId(lastName, postcode);
627	        return (normalizedTelephone == null ? "" : normalizedTelephone)
628	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
629	            + "|" + (household == null ? "" : household);
630	    }
631	
632	    /**
633	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
634	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
635	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
636	     * value is deterministic in those two fields.
637	     *
638	     * @param customerCode the owner's customer code, possibly {@code null}
639	     * @param registrationDate the owner's registration date, possibly {@code null}
640	     * @return the membership number, or {@code null} if either field is {@code null}
641	     */
642	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
643	        if (customerCode == null || registrationDate == null) {
644	            return null;
645	        }
646	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
647	    }
648	
649	    /**
650	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
651	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
652	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
653	     * and gains 3 when the owner's tenure is more than 365 days (the tenure being the number of days
654	     * from {@code registrationDate} to today). Because a newly created owner has zero tenure, the
655	     * tenure points accrue only once the owner has been a member for over a year.
656	     *
657	     * @param namesakeCount the owner's namesake count, possibly {@code null}
658	     * @param email the owner's email, possibly {@code null}
659	     * @param householdCount the number of members in the owner's household, possibly {@code null}
660	     * @param registrationDate the owner's registration date, possibly {@code null}
661	     * @return the membership points, a non-negative integer
662	     */
663	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
664	            LocalDate registrationDate) {
665	        int points = 0;
666	        if (email != null && !email.isEmpty()) {
667	            points += 2;
668	        }
669	        if (namesakeCount != null && namesakeCount == 0) {
670	            points += 1;
671	        }
672	        if (householdCount != null && householdCount >= 3) {
673	            points += 2;
674	        }
675	        if (registrationDate != null
676	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
677	            points += 3;
678	        }
679	        return points;
680	    }
681	
682	    /**
683	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
684	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
685	     *
686	     * @param membershipPoints the owner's membership points
687	     * @return the membership level, an integer from 1 to 4
688	     */
689	    public static int membershipLevel(int membershipPoints) {
690	        if (membershipPoints >= 6) {
691	            return 4;
692	        }
693	        if (membershipPoints >= 4) {
694	            return 3;
695	        }
696	        if (membershipPoints >= 2) {
697	            return 2;
698	        }
699	        return 1;
700	    }
701	
702	    /**
703	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
704	     * for postcode validation, keyed by the exact city name.
705	     */
706	    private static final Map<String, String> CITY_REGION = Map.of(
707	        "Sydney", "NSW",
708	        "Melbourne", "VIC",
709	        "Brisbane", "QLD");
710	
711	    /**
712	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
713	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
714	     * Because the customer code's region is itself derived from the postcode, the locality now shares
715	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
716	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
717	     *
718	     * @param customerCode the owner's customer code, possibly {@code null}
719	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
720	     */
721	    public static String locality(String customerCode) {
722	        if (customerCode == null) {
723	            return "UNKNOWN";
724	        }
725	        int dash = customerCode.indexOf('-');
726	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
727	    }
728	
729	    /**
730	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
731	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
732	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
733	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
734	     */
735	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
736	        "NSW", "Australia/Sydney",
737	        "VIC", "Australia/Melbourne",
738	        "QLD", "Australia/Brisbane");
739	
740	    /**
741	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
742	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
743	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
744	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
745	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
746	     * timezone and yields {@code null}.
747	     *
748	     * @param customerCode the owner's customer code, possibly {@code null}
749	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
750	     */
751	    public static String timezone(String customerCode) {
752	        return REGION_TIMEZONE.get(locality(customerCode));
753	    }
754	
755	    /**
756	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
757	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
758	     *
759	     * @param city the owner's city, possibly {@code null}
760	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
761	     */
762	    private static String regionForCity(String city) {
763	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
764	    }
765	
766	    /**
767	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
768	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
769	     * inclusive low and high bound of the region's valid 4-digit postcodes
770	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
771	     * table (including {@code 'UNKNOWN'}) places no range constraint.
772	     */
773	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
774	        "NSW", new int[] {2000, 2099},
775	        "VIC", new int[] {3000, 3099},
776	        "QLD", new int[] {4000, 4099});
777	
778	    /**
779	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
780	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
781	     * digits, or one that falls in no known range resolves to {@code null}.
782	     *
783	     * @param postcode the owner's postcode, possibly {@code null}
784	     * @return the matching region, or {@code null} when no range contains the postcode
785	     */
786	    private static String regionForPostcode(String postcode) {
787	        if (postcode == null || !postcode.matches("\\d{4}")) {
788	            return null;
789	        }
790	        int value = Integer.parseInt(postcode);
791	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
792	            int[] range = entry.getValue();
793	            if (value >= range[0] && value <= range[1]) {
794	                return entry.getKey();
795	            }
796	        }
797	        return null;
798	    }
799	
800	    /**
801	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
802	     * {@code null} or empty postcode is always valid. When present it must be exactly four
803	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
804	     * range the value must fall within that inclusive range. A city with no known region accepts
805	     * any four-digit postcode. This is the single source of
806	     * truth for postcode validity, shared by the DTO validation and any persistence path.
807	     *
808	     * @param postcode the owner's postcode, possibly {@code null}
809	     * @param city the owner's city, possibly {@code null}
810	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
811	     */
812	    public static boolean isPostcodeValidForCity(String postcode, String city) {
813	        if (postcode == null || postcode.isEmpty()) {
814	            return true;
815	        }
816	        if (!postcode.matches("\\d{4}")) {
817	            return false;
818	        }
819	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
820	        if (range == null) {
821	            return true;
822	        }
823	        int value = Integer.parseInt(postcode);
824	        return value >= range[0] && value <= range[1];
825	    }
826	
827	    /**
828	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
829	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
830	     * value is deterministic in the customer code and is the standard Luhn check digit: each
831	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
832	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
833	     * brings the weighted sum up to the next multiple of ten.
834	     *
835	     * @param customerCode the owner's customer code, possibly {@code null}
836	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
837	     */
838	    public static Integer checkDigit(String customerCode) {
839	        if (customerCode == null) {
840	            return null;
841	        }
842	        int sum = 0;
843	        boolean dbl = true;
844	        for (int i = customerCode.length() - 1; i >= 0; i--) {
845	            char c = customerCode.charAt(i);
846	            if (c < '0' || c > '9') {
847	                continue;
848	            }
849	            int d = c - '0';
850	            if (dbl) {
851	                d *= 2;
852	                if (d > 9) {
853	                    d -= 9;
854	                }
855	            }
856	            sum += d;
857	            dbl = !dbl;
858	        }
859	        return (10 - (sum % 10)) % 10;
860	    }
861	
862	    /**
863	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
864	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
865	     * is deterministic in the email.
866	     *
867	     * @param email the owner's email, possibly {@code null}
868	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
869	     */
870	    public static String contactPreference(String email) {
871	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
872	    }
873	
874	    /**
875	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
876	     * When a title is present the result is the title and the last name separated by a single space
877	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
878	     * value is deterministic in those two fields.
879	     *
880	     * @param title the owner's honorific title, possibly {@code null} or blank
881	     * @param lastName the owner's last name, possibly {@code null}
882	     * @return the composed salutation
883	     */
884	    public static String salutation(String title, String lastName) {
885	        if (title == null || title.isBlank()) {
886	            return lastName;
887	        }
888	        return title + " " + lastName;
889	    }
890	
891	    /**
892	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
893	     * date. The age in whole years is the number of completed years between {@code birthDate} and
894	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
895	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
896	     * two fields and is only defined when both are present.
897	     *
898	     * @param birthDate the owner's date of birth, possibly {@code null}
899	     * @param registrationDate the owner's registration date, possibly {@code null}
900	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
901	     *     is {@code null}
902	     */
903	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
904	        if (birthDate == null || registrationDate == null) {
905	            return null;
906	        }
907	        int age = Period.between(birthDate, registrationDate).getYears();
908	        if (age < 18) {
909	            return "MINOR";
910	        }
911	        if (age < 65) {
912	            return "ADULT";
913	        }
914	        return "SENIOR";
915	    }
916	
917	    protected Set<Pet> getPetsInternal() {
918	        if (this.pets == null) {
919	            this.pets = new HashSet<>();
920	        }
921	        return this.pets;
922	    }
923	
924	    protected void setPetsInternal(Set<Pet> pets) {
925	        this.pets = pets;
926	    }
927	
928	    public List<Pet> getPets() {
929	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
930	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
931	        return Collections.unmodifiableList(sortedPets);
932	    }
933	
934	    public void setPets(List<Pet> pets) {
935	        this.pets = new HashSet<>(pets);
936	    }
937	
938	    public void addPet(Pet pet) {
939	        getPetsInternal().add(pet);
940	        pet.setOwner(this);
941	    }
942	
943	    /**
944	     * Return the Pet with the given name, or null if none found for this Owner.
945	     *
946	     * @param name to test
947	     * @return true if pet name is already in use
948	     */
949	    public Pet getPet(String name) {
950	        return getPet(name, false);
951	    }
952	
953	    /**
954	     * Return the Pet with the given name, or null if none found for this Owner.
955	     *
956	     * @param name to test
957	     * @return true if pet name is already in use
958	     */
959	    public Pet getPet(String name, boolean ignoreNew) {
960	        name = name.toLowerCase();
961	        for (Pet pet : getPetsInternal()) {
962	            if (!ignoreNew || !pet.isNew()) {
963	                String compName = pet.getName();
964	                compName = compName.toLowerCase();
965	                if (compName.equals(name)) {
966	                    return pet;
967	                }
968	            }
969	        }
970	        return null;
971	    }
972	
973	    public Pet getPet(Integer petId) {
974	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
975	    }
976	
977	    @Override
978	    public String toString() {
979	        return new ToStringCreator(this)
980	
981	            .append("id", this.getId())
982	            .append("new", this.isNew())
983	            .append("lastName", this.getLastName())
984	            .append("firstName", this.getFirstName())
985	            .append("address", this.address)
986	            .append("city", this.city)
987	            .append("telephone", this.telephone)
988	            .toString();
989	    }
990	}
