263	
264	    @Override
265	    @Transactional
266	    public void saveOwner(Owner owner) throws DataAccessException {
267	        saveOwner(owner, false);
268	    }
269	
270	    /**
271	     * Save an owner, enforcing the create-time business rules.
272	     *
273	     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
274	     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
275	     * same household. On create, a second owner in an existing household is rejected as a household
276	     * duplicate (see {@link #assertHouseholdIsUnique(Owner)}) <em>unless</em> {@code sharesHousehold}
277	     * is set, in which case it is accepted as a declared household member. The {@code sharesHousehold}
278	     * flag therefore only bypasses that duplicate block; a declared member is also not flagged as a
279	     * possible (suspected) duplicate.
280	     */
281	    @Override
282	    @Transactional
283	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
284	        boolean isCreate = owner.isNew();
285	        assertEmailDomainAllowed(owner);
286	        assertIdentityIsUnique(owner);
287	        if (owner.isNew()) {
288	            assertCityHasCapacity(owner);
289	            if (!sharesHousehold) {
290	                assertHouseholdIsUnique(owner);
291	            }
292	        }
293	        if (owner.getRegistrationDate() == null) {
294	            owner.setRegistrationDate(LocalDate.now());
295	        }
296	        assertRegistrationDateNotInFuture(owner);
297	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
298	        if (owner.isNew()) {
299	            assertDailyRegistrationLimit(owner);
300	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
301	        }
302	        if (owner.isNew() && owner.getCustomerCode() == null) {
303	            owner.setCustomerCode(generateCustomerCode(owner));
304	        }
305	        if (owner.isNew() && owner.getNamesakeCount() == null) {
306	            owner.setNamesakeCount(countNamesakes(owner));
307	        }
308	        if (owner.isNew() && owner.getHouseholdCount() == null) {
309	            owner.setHouseholdCount(countHouseholdMembers(owner));
310	        }
311	        if (owner.isNew()) {
312	            assignPossibleDuplicate(owner, sharesHousehold);
313	        }
314	        ownerRepository.save(owner);
315	        if (isCreate) {
316	            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
317	                owner.getRegistrationDate());
318	            int membershipLevel = Owner.membershipLevel(Owner.membershipPoints(
319	                owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdCount(),
320	                owner.getRegistrationDate()));
321	            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
322	                    + "membershipLevel={} membershipNumber={}",
323	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
324	                membershipLevel, membershipNumber);
325	        }
326	    }
327	
328	    /**
329	     * Count the existing owners that, at the moment this owner is created, share its first name
330	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
331	     * it never counts itself. This value is deterministic given the current data, so it is computed
332	     * once at creation time and stored.
333	     */
334	    private Integer countNamesakes(Owner owner) {
335	        String firstName = owner.getFirstName();
336	        String lastName = owner.getLastName();
337	        if (firstName == null || lastName == null) {
338	            return 0;
339	        }
340	        return (int) ownerRepository.findAll().stream()
341	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
342	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
343	                && lastName.equalsIgnoreCase(existing.getLastName()))
344	            .count();
345	    }
346	
347	    /**
348	     * Count the members of this owner's household at the moment it is created, i.e. the number of
349	     * owners sharing its household id (same last name and postcode, see
350	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
351	     * household id (missing last name or postcode) is counted as a single-member household. The value
352	     * is deterministic given the current data, so it is computed once at creation time and stored.
353	     */
354	    private Integer countHouseholdMembers(Owner owner) {
355	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
356	        if (householdId == null) {
357	            return 1;
358	        }
359	        long others = ownerRepository.findAll().stream()
360	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
361	            .filter(existing -> householdId.equals(
362	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
363	            .count();
364	        return (int) others + 1;
365	    }
366	
367	    /**
368	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
369	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
370	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
371	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
372	     * base value is deterministic in those fields and carries no sequence number (see
373	     * {@link Owner#customerCode(String, String, String)}).
374	     *
375	     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
376	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
377	     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
378	     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
379	     * returned unchanged.
380	     */
381	    private String generateCustomerCode(Owner owner) {
382	        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
383	        if (base == null) {
384	            return null;
385	        }
386	        Set<String> existing = ownerRepository.findAll().stream()
387	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
388	            .map(Owner::getCustomerCode)
389	            .filter(Objects::nonNull)
390	            .collect(Collectors.toSet());
391	        if (!existing.contains(base)) {
392	            return base;
393	        }
394	        int n = 2;
395	        while (existing.contains(base + "-" + n)) {
396	            n++;
397	        }
398	        return base + "-" + n;
399	    }
400	
401	    /**
402	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
403	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
404	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
405	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
406	     * existing owner that shares this owner's household id (same last name and postcode, see
407	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
408	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
409	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
410	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
411	     *
412	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
413	     * deliberately joins an existing household, so it is left unflagged.
414	     */
415	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
416	        if (sharesHousehold) {
417	            owner.setPossibleDuplicate(false);
418	            owner.setPossibleDuplicateOf(null);
419	            return;
420	        }
421	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
422	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
423	        Integer match = null;
424	        if (householdId != null) {
425	            match = ownerRepository.findAll().stream()
426	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
427	                .filter(existing -> householdId.equals(
428	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
429	                .filter(existing -> !Objects.equals(normalizedTelephone,
430	                    Owner.normalizeTelephone(existing.getTelephone())))
431	                .map(Owner::getId)
432	                .filter(Objects::nonNull)
433	                .min(Integer::compareTo)
434	                .orElse(null);
435	        }
436	        owner.setPossibleDuplicate(match != null);
437	        owner.setPossibleDuplicateOf(match);
438	    }
439	
440	    /**
441	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
442	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
443	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
444	     * constraint.
445	     */
446	    private void assertEmailDomainAllowed(Owner owner) {
447	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
448	            throw new DisposableEmailDomainException(owner.getEmail());
449	        }
450	    }
451	
452	    /**
453	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
454	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
455	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
456	     * (normalized telephone, normalized email (or empty) and household id, see
457	     * {@link Owner#identityKey(String, String, String, String)}).
458	     *
459	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
460	     * key when their normalized telephones already match; the normalized telephone is therefore the
461	     * decisive component and is what this check compares. Consequently two members of the same
462	     * household with different telephones have different identity keys and are both allowed, while
463	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
464	     * excluded by id so updating an owner in place never conflicts with itself.
465	     */
466	    private void assertIdentityIsUnique(Owner owner) {
467	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
468	        if (normalizedTelephone == null) {
469	            return;
470	        }
471	        boolean duplicate = ownerRepository.findAll().stream()
472	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
473	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
474	            .anyMatch(normalizedTelephone::equals);
475	        if (duplicate) {
476	            throw new DuplicateIdentityException(Owner.identityKey(
477	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
478	        }
479	    }
480	
481	    /**
482	     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
483	     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
484	     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
485	     * postcode are the same household and a second such owner is a household duplicate. The owner
486	     * being saved is excluded by id, and an owner with no derivable household id (missing last name
487	     * or postcode) places no constraint. Callers bypass this check for a declared household member
488	     * ({@code sharesHousehold} set).
489	     */
490	    private void assertHouseholdIsUnique(Owner owner) {
491	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
492	        if (householdId == null) {
493	            return;
494	        }
495	        boolean duplicate = ownerRepository.findAll().stream()
496	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
497	            .map(existing -> Owner.householdId(existing.getLastName(), existing.getPostcode()))
498	            .anyMatch(householdId::equals);
499	        if (duplicate) {
500	            throw new DuplicateIdentityException(Owner.identityKey(
501	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
502	        }
503	    }
504	
505	    /**
506	     * Enforce that the owner's city has not yet reached its capacity, throwing
507	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
508	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
509	     */
510	    private void assertCityHasCapacity(Owner owner) {
511	        String city = owner.getCity();
512	        if (city == null) {
513	            return;
514	        }
515	        long count = ownerRepository.findAll().stream()
516	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
517	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
518	            .count();
519	        if (count >= MAX_OWNERS_PER_CITY) {
520	            throw new CityAtCapacityException(city);
521	        }
522	    }
523	
524	    /**
525	     * Enforce that the owner's registration date is not later than the current server date, throwing
526	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
527	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
528	     * harmless no-op for that case.
529	     */
530	    private void assertRegistrationDateNotInFuture(Owner owner) {
531	        LocalDate registrationDate = owner.getRegistrationDate();
532	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
533	            throw new FutureRegistrationDateException(registrationDate);
534	        }
535	    }
536	
537	    /**
538	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
539	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
540	     * the effective registration date (whether supplied in the request or defaulted to the server
541	     * date) so that every value derived from it&mdash;such as the membership number's year segment
542	     * and the daily create-limit counting&mdash;uses the adjusted business day.
543	     */
544	    private static LocalDate rollToBusinessDay(LocalDate date) {
545	        if (date == null) {
546	            return null;
547	        }
548	        DayOfWeek dayOfWeek = date.getDayOfWeek();
549	        if (dayOfWeek == DayOfWeek.SATURDAY) {
550	            return date.plusDays(2);
551	        }
552	        if (dayOfWeek == DayOfWeek.SUNDAY) {
553	            return date.plusDays(1);
554	        }
555	        return date;
556	    }
557	
558	    /**
559	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
560	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
561	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
562	     * is excluded by id.
563	     */
564	    private void assertDailyRegistrationLimit(Owner owner) {
565	        LocalDate registrationDate = owner.getRegistrationDate();
566	        if (registrationDate == null) {
567	            return;
568	        }
569	        long count = ownerRepository.findAll().stream()
570	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
571	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
572	            .count();
573	        if (count >= MAX_OWNERS_PER_DAY) {
574	            throw new DailyRegistrationLimitException(registrationDate);
575	        }
576	    }
577	
578	    /**
579	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
580	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
581	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
582	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
583	     * stored on the owner.
584	     */
585	    private boolean computeBulkSignupWarning(Owner owner) {
586	        LocalDate registrationDate = owner.getRegistrationDate();
587	        if (registrationDate == null) {
588	            return false;
589	        }
590	        long count = ownerRepository.findAll().stream()
591	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
592	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
593	            .count();
594	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
595	    }
596	
597	    @Override
598	    @Transactional(readOnly = true)
599	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
600	        return ownerRepository.findByLastName(lastName);
601	    }
602	
603	    @Override
604	    @Transactional(readOnly = true)
605	    public Collection<Visit> findVisitsByPetId(int petId) {
606	        return visitRepository.findByPetId(petId);
607	    }
608	
609	    @Override
610	    @Transactional(readOnly = true)
611	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
612	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
613	    }
614	
615	    private <T> T findEntityById(Supplier<T> supplier) {
616	        try {
617	            return supplier.get();
618	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
619	            // Just ignore not found exceptions for Jdbc/Jpa realization
