        visitRepository.save(visit);

    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Vet> findVets() throws DataAccessException {
        return vetRepository.findAll();
    }

    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        saveOwner(owner, false);
    }

    /**
     * Save an owner, enforcing the create-time business rules.
     *
     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
     * same household. On create, a second owner in an existing household is rejected as a household
     * duplicate (see {@link #assertHouseholdIsUnique(Owner)}) <em>unless</em> {@code sharesHousehold}
     * is set, in which case it is accepted as a declared household member. The {@code sharesHousehold}
     * flag therefore only bypasses that duplicate block; a declared member is also not flagged as a
     * possible (suspected) duplicate.
     */
    @Override
    @Transactional
    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
        boolean isCreate = owner.isNew();
        assertEmailDomainAllowed(owner);
        assertIdentityIsUnique(owner);
        if (owner.isNew()) {
            assertCityHasCapacity(owner);
            if (!sharesHousehold) {
                assertHouseholdIsUnique(owner);
            }
        }
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        assertRegistrationDateNotInFuture(owner);
        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
        if (owner.isNew()) {
            assertDailyRegistrationLimit(owner);
            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
        }
        if (owner.isNew() && owner.getCustomerCode() == null) {
            owner.setCustomerCode(generateCustomerCode(owner));
        }
        if (owner.isNew() && owner.getNamesakeCount() == null) {
            owner.setNamesakeCount(countNamesakes(owner));
        }
        if (owner.isNew() && owner.getHouseholdCount() == null) {
            owner.setHouseholdCount(countHouseholdMembers(owner));
        }
        if (owner.isNew()) {
            assignPossibleDuplicate(owner, sharesHousehold);
        }
        ownerRepository.save(owner);
        if (isCreate) {
            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
                owner.getRegistrationDate());
            int membershipLevel = Owner.membershipLevel(Owner.membershipPoints(
                owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdCount(),
                owner.getRegistrationDate()));
            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
                    + "membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                membershipLevel, membershipNumber);
        }
    }

    /**
     * Count the existing owners that, at the moment this owner is created, share its first name
     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
     * it never counts itself. This value is deterministic given the current data, so it is computed
     * once at creation time and stored.
     */
    private Integer countNamesakes(Owner owner) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        if (firstName == null || lastName == null) {
            return 0;
        }
        return (int) ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
                && lastName.equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /**
     * Count the members of this owner's household at the moment it is created, i.e. the number of
     * owners sharing its household id (same last name and postcode, see
     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
     * household id (missing last name or postcode) is counted as a single-member household. The value
     * is deterministic given the current data, so it is computed once at creation time and stored.
     */
    private Integer countHouseholdMembers(Owner owner) {
        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
        if (householdId == null) {
            return 1;
        }
        long others = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> householdId.equals(
                Owner.householdId(existing.getLastName(), existing.getPostcode())))
            .count();
        return (int) others + 1;
    }

    /**
     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
     * base value is deterministic in those fields and carries no sequence number (see
     * {@link Owner#customerCode(String, String, String)}).
     *
     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
     * returned unchanged.
     */
    private String generateCustomerCode(Owner owner) {
        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
        if (base == null) {
            return null;
        }
        Set<String> existing = ownerRepository.findAll().stream()
            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
            .map(Owner::getCustomerCode)
            .filter(Objects::nonNull)
            .collect(Collectors.toSet());
        if (!existing.contains(base)) {
            return base;
        }
        int n = 2;
        while (existing.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
     * existing owner that shares this owner's household id (same last name and postcode, see
     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
     *
     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
     * deliberately joins an existing household, so it is left unflagged.
     */
    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
        if (sharesHousehold) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return;
        }
        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
        Integer match = null;
        if (householdId != null) {
            match = ownerRepository.findAll().stream()
                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
                .filter(existing -> householdId.equals(
                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
                .filter(existing -> !Objects.equals(normalizedTelephone,
                    Owner.normalizeTelephone(existing.getTelephone())))
                .map(Owner::getId)
                .filter(Objects::nonNull)
                .min(Integer::compareTo)
                .orElse(null);
        }
        owner.setPossibleDuplicate(match != null);
        owner.setPossibleDuplicateOf(match);
    }

    /**
     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
     * constraint.
     */
    private void assertEmailDomainAllowed(Owner owner) {
        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
            throw new DisposableEmailDomainException(owner.getEmail());
        }
    }

    /**
     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
     * separate telephone, email and household duplicate checks into the one {@code identityKey}
     * (normalized telephone, normalized email (or empty) and household id, see
     * {@link Owner#identityKey(String, String, String, String)}).
     *
     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
     * key when their normalized telephones already match; the normalized telephone is therefore the
     * decisive component and is what this check compares. Consequently two members of the same
     * household with different telephones have different identity keys and are both allowed, while
     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
     * excluded by id so updating an owner in place never conflicts with itself.
     */
    private void assertIdentityIsUnique(Owner owner) {
        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
        if (normalizedTelephone == null) {
            return;
        }
        boolean duplicate = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
            .anyMatch(normalizedTelephone::equals);
        if (duplicate) {
            throw new DuplicateIdentityException(Owner.identityKey(
                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
        }
    }

    /**
     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
     * postcode are the same household and a second such owner is a household duplicate. The owner
     * being saved is excluded by id, and an owner with no derivable household id (missing last name
     * or postcode) places no constraint. Callers bypass this check for a declared household member
     * ({@code sharesHousehold} set).
     */
    private void assertHouseholdIsUnique(Owner owner) {
        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
        if (householdId == null) {
            return;
        }
        boolean duplicate = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .map(existing -> Owner.householdId(existing.getLastName(), existing.getPostcode()))
            .anyMatch(householdId::equals);
        if (duplicate) {
            throw new DuplicateIdentityException(Owner.identityKey(
                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
        }
    }

    /**
     * Enforce that the owner's city has not yet reached its capacity, throwing
     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
     */
    private void assertCityHasCapacity(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
            return;
        }
        long count = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
            .count();
        if (count >= MAX_OWNERS_PER_CITY) {
            throw new CityAtCapacityException(city);
        }
    }

    /**
     * Enforce that the owner's registration date is not later than the current server date, throwing
     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
     * harmless no-op for that case.
     */
    private void assertRegistrationDateNotInFuture(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(registrationDate);
        }
    }

    /**
     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
     * the effective registration date (whether supplied in the request or defaulted to the server
     * date) so that every value derived from it&mdash;such as the membership number's year segment
     * and the daily create-limit counting&mdash;uses the adjusted business day.
     */
    private static LocalDate rollToBusinessDay(LocalDate date) {
        if (date == null) {
            return null;
        }
        DayOfWeek dayOfWeek = date.getDayOfWeek();
        if (dayOfWeek == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (dayOfWeek == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }

    /**
     * Enforce that the owner's registration day has not yet reached its capacity, throwing
     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
     * already registered on that day (counted by {@code registrationDate}). The owner being saved
     * is excluded by id.
     */
    private void assertDailyRegistrationLimit(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return;
        }
        long count = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
        if (count >= MAX_OWNERS_PER_DAY) {
            throw new DailyRegistrationLimitException(registrationDate);
        }
    }

    /**
     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
     * the daily-limit rule this reflects the state at creation time, so it is computed once and
     * stored on the owner.
     */
    private boolean computeBulkSignupWarning(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return false;
        }
        long count = ownerRepository.findAll().stream()
            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
        return count > BULK_SIGNUP_WARNING_THRESHOLD;
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

